import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.find.js";
import "core-js/modules/esnext.iterator.for-each.js";
import { ref, computed, onMounted } from "vue";
import { collection, getDocs, addDoc, deleteDoc, doc, serverTimestamp } from "firebase/firestore";
import { db, storage } from "../firebase";
import { ref as storageRef, uploadBytes, getDownloadURL, deleteObject } from "firebase/storage";
export default {
  name: "InvitationToBid",
  setup() {
    // State
    const invitations = ref([]);
    const archivedInvitations = ref([]);
    const searchQuery = ref("");
    const showCreateForm = ref(false);

    // Form fields (Create)
    const projectName = ref("");
    const location = ref("");
    const approvedBudget = ref("");
    const contractDuration = ref("");
    const deliverySchedule = ref("");
    const deadline = ref("");
    const timerDuration = ref("");
    const pdfFile = ref(null);
    const supportingFiles = ref([]);

    // Form fields (Edit)
    const editInvitationId = ref("");
    const editProjectName = ref("");
    const editLocation = ref("");
    const editApprovedBudget = ref("");
    const editContractDuration = ref("");
    const editDeliverySchedule = ref("");
    const editDeadline = ref("");
    const editTimerDuration = ref("");
    const editPdfFile = ref(null);
    const editSupportingFiles = ref([]);

    // Modals
    const viewInvitationModal = ref(false);
    const editInvitationModal = ref(false);
    const deleteInvitationModal = ref(false);
    const archiveInvitationModal = ref(false);

    // View data
    const selectedInvitation = ref(null);

    // Firestore collection refs
    const invitationsCol = collection(db, "invitations");
    const archivedCol = collection(db, "archivedInvitations");

    // Computed: Filtered active invitations
    const filteredInvitations = computed(() => {
      if (!searchQuery.value) return invitations.value;
      return invitations.value.filter(inv => inv.projectName?.toLowerCase().includes(searchQuery.value.toLowerCase()));
    });

    // Fetch Active Invitations
    const fetchInvitations = async () => {
      invitations.value = [];
      const snapshot = await getDocs(invitationsCol);
      snapshot.forEach(docSnap => {
        const data = docSnap.data();
        invitations.value.push({
          id: docSnap.id,
          ...data
        });
      });
    };

    // Fetch Archived Invitations
    const fetchArchivedInvitations = async () => {
      archivedInvitations.value = [];
      const snapshot = await getDocs(archivedCol);
      snapshot.forEach(docSnap => {
        const data = docSnap.data();
        archivedInvitations.value.push({
          id: docSnap.id,
          ...data
        });
      });
    };

    // Create Invitation
    const createInvitation = async () => {
      try {
        let pdfUrl = "";
        let supportingUrls = [];
        if (pdfFile.value) {
          const fileRef = storageRef(storage, `pdfs/${pdfFile.value.name}`);
          await uploadBytes(fileRef, pdfFile.value);
          pdfUrl = await getDownloadURL(fileRef);
        }
        if (supportingFiles.value.length) {
          for (let file of supportingFiles.value) {
            const fileRef = storageRef(storage, `supporting/${file.name}`);
            await uploadBytes(fileRef, file);
            supportingUrls.push(await getDownloadURL(fileRef));
          }
        }
        const expiresAt = timerDuration.value ? new Date(Date.now() + timerDuration.value * 60 * 60 * 1000) : null;
        await addDoc(invitationsCol, {
          projectName: projectName.value,
          location: location.value,
          approvedBudget: approvedBudget.value,
          contractDuration: contractDuration.value,
          deliverySchedule: deliverySchedule.value,
          deadline: deadline.value,
          pdfUrl,
          supportingUrls,
          expiresAt,
          createdAt: serverTimestamp()
        });
        resetForm();
        await fetchInvitations();
        showNotification("Invitation created successfully");
      } catch (error) {
        console.error("Error creating invitation:", error);
      }
    };

    // Restore Archived Invitation
    const restoreArchivedInvitation = async (id, newTimerHours) => {
      try {
        const invitationDoc = archivedInvitations.value.find(inv => inv.id === id);
        if (!invitationDoc) return;
        const expiresAt = newTimerHours ? new Date(Date.now() + newTimerHours * 60 * 60 * 1000) : null;

        // Add back to active invitations
        await addDoc(invitationsCol, {
          ...invitationDoc,
          expiresAt,
          restoredAt: serverTimestamp()
        });

        // Remove from archived
        await deleteDoc(doc(db, "archivedInvitations", id));
        await fetchInvitations();
        await fetchArchivedInvitations();
        showNotification("Archived invitation restored");
      } catch (error) {
        console.error("Error restoring invitation:", error);
      }
    };

    // Helpers
    const resetForm = () => {
      projectName.value = "";
      location.value = "";
      approvedBudget.value = "";
      contractDuration.value = "";
      deliverySchedule.value = "";
      deadline.value = "";
      timerDuration.value = "";
      pdfFile.value = null;
      supportingFiles.value = [];
    };
    const showNotification = message => {
      const note = document.createElement("div");
      note.className = "notification";
      note.innerText = message;
      document.body.appendChild(note);
      setTimeout(() => note.remove(), 3000);
    };
    const getTimeLeft = expiresAt => {
      if (!expiresAt) return "No timer";
      const diff = expiresAt.toDate ? expiresAt.toDate() - Date.now() : expiresAt - Date.now();
      if (diff <= 0) return "Expired";
      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor(diff % (1000 * 60 * 60) / (1000 * 60));
      return `${hours}h ${minutes}m`;
    };
    onMounted(async () => {
      await fetchInvitations();
      await fetchArchivedInvitations();
    });
    return {
      invitations,
      archivedInvitations,
      searchQuery,
      showCreateForm,
      projectName,
      location,
      approvedBudget,
      contractDuration,
      deliverySchedule,
      deadline,
      timerDuration,
      pdfFile,
      supportingFiles,
      editInvitationId,
      editProjectName,
      editLocation,
      editApprovedBudget,
      editContractDuration,
      editDeliverySchedule,
      editDeadline,
      editTimerDuration,
      editPdfFile,
      editSupportingFiles,
      viewInvitationModal,
      editInvitationModal,
      deleteInvitationModal,
      archiveInvitationModal,
      selectedInvitation,
      filteredInvitations,
      createInvitation,
      restoreArchivedInvitation,
      getTimeLeft
    };
  }
};
